// teste70-rdo-removal/src/utils/publicLinkSecurity.ts
var generateSecurePublicToken = (purpose) => {
  const random = new Uint8Array(24);
  globalThis.crypto.getRandomValues(random);
  const entropy = Array.from(random, (byte) => byte.toString(16).padStart(2, "0")).join("");
  return `${purpose}-${entropy}`;
};

// teste70-rdo-removal/src/utils/apontamentoRamosConfig.ts
var APONTAMENTO_LINK_TOKEN = generateSecurePublicToken("apontamento");

